// users.controller.ts
@Controller('users')
export class UsersController {
  constructor(private readonly usersService: UsersService) {}

  @Get(':id')
  async getUser(@Param('id') id: string) {
    try {
      const user = await this.usersService.findById(id);
      // Hand-built success envelope, assembled locally in this handler.
      return {
        statusCode: 200,
        message: 'OK',
        data: user,
      };
    } catch (e) {
      // BUG: swallows the real failure and still answers with HTTP 200.
      // Client + any monitoring on status code both see "success".
      return {
        statusCode: 200,
        message: 'Something went wrong',
        data: null,
      };
    }
  }
}

// orders.controller.ts
@Controller('orders')
export class OrdersController {
  constructor(private readonly ordersService: OrdersService) {}

  @Get(':id')
  async getOrder(@Param('id') id: string) {
    try {
      const order = await this.ordersService.findById(id);
      // Hand-built success envelope again — but shaped differently: `result`, not `data`,
      // and no `timestamp` field either. Already disagrees with UsersController above.
      return {
        statusCode: 200,
        message: 'OK',
        result: order,
      };
    } catch (e) {
      // BUG: flattens a domain "not found" into a generic 500, AND leaks the raw
      // internal error message straight to the client.
      throw new HttpException(
        {
          statusCode: 500,
          error: e.message,
        },
        500,
      );
    }
  }
}

// api-client.ts
export async function fetchUserAndOrder(userId: string, orderId: string) {
  const userRes = await http.get(`/users/${userId}`);
  const orderRes = await http.get(`/orders/${orderId}`);

  // The client can't parse every response through one path — it has to know,
  // per-endpoint, whether the payload lives at `.data` or `.result`.
  const user = userRes.data.data;
  const order = orderRes.data.result;

  return { user, order };
}
